71:       get: function () {
72:         if (this.index) {
73:           return (this.index.isObjectProperty())
74:               ? this.index.getObjectProperty()
75:               : '';
76:         }
77:         else {
78:           return this.object.name || '';
79:         }
80:       }.bind(this),
81:       set: function () {
82:         throw new Error('Cannot assign a new name, name is read-only');
83:       }
84:     });
85:   }
