87:   AssignmentNode.prototype = new Node();
88: 
89:   AssignmentNode.prototype.type = 'AssignmentNode';
90: 
91:   AssignmentNode.prototype.isAssignmentNode = true;
92: 
93:   /**
94:    * Compile the node to javascript code
95:    * @param {AssignmentNode} node The node to be compiled
96:    * @param {Object} defs     Object which can be used to define functions
97:    *                          or constants globally available for the compiled
98:    *                          expression
99:    * @param {Object} args     Object with local function arguments, the key is
100:    *                          the name of the argument, and the value is `true`.
101:    *                          The object may not be mutated, but must be
102:    *                          extended instead.
103:    * @private
104:    */
105:   function compileAssignmentNode (node, defs, args) {
106:     defs.assign = assign;
107:     defs.access = access;
108:     defs.getSafeProperty = getSafeProperty;
109:     defs.setSafeProperty = setSafeProperty;
110: 
111:     var size;
112:     var object = compile(node.object, defs, args);
113:     var index = node.index ? compile(node.index, defs, args) : null;
114:     var value = compile(node.value, defs, args);
115:     var jsName = stringify(node.object.name);
116: 
117:     if (!node.index) {
118:       // apply a variable to the scope, for example `a=2`
119:       if (!node.object.isSymbolNode) {
120:         throw new TypeError('SymbolNode expected as object');
121:       }
122: 
123:       return 'setSafeProperty(scope, ' + jsName + ', ' + value + ')';
124:     }
125:     else if (node.index.isObjectProperty()) {
126:       // apply an object property for example `a.b=2`
127:       var jsProp = stringify(node.index.getObjectProperty());
128:       return 'setSafeProperty(' + object + ', ' + jsProp + ', ' + value + ')';
129:     }
130:     else if (node.object.isSymbolNode) {
131:       // update a matrix subset, for example `a[2]=3`
132:       size = node.index.needsSize() ? 'var size = math.size(object).valueOf();' : '';
133: 
134:       // apply updated object to scope
135:       return '(function () {' +
136:           '  var object = ' + object + ';' +
137:           '  var value = ' + value + ';' +
138:           '  ' + size +
139:           '  setSafeProperty(scope, ' + jsName + ', assign(object, ' + index + ', value));' +
140:           '  return value;' +
141:           '})()';
142:     }
143:     else { // node.object.isAccessorNode === true
144:       // update a matrix subset, for example `a.b[2]=3`
145:       size = node.index.needsSize() ? 'var size = math.size(object).valueOf();' : '';
146: 
147:       // we will not use the compile function of the AccessorNode, but compile it
148:       // ourselves here as we need the parent object of the AccessorNode:
149:       // wee need to apply the updated object to parent object
150:       var parentObject = compile(node.object.object, defs, args);
151: 
152:       if (node.object.index.isObjectProperty()) {
153:         var jsParentProperty = stringify(node.object.index.getObjectProperty());
154:         return '(function () {' +
155:             '  var parent = ' + parentObject + ';' +
156:             '  var object = getSafeProperty(parent, ' + jsParentProperty + ');' + // parentIndex is a property
157:             '  var value = ' + value + ';' +
158:             size +
159:             '  setSafeProperty(parent, ' + jsParentProperty + ', assign(object, ' + index + ', value));' +
160:             '  return value;' +
161:             '})()';
162:       }
163:       else {
164:         // if some parameters use the 'end' parameter, we need to calculate the size
165:         var parentSize = node.object.index.needsSize() ? 'var size = math.size(parent).valueOf();' : '';
166:         var parentIndex = compile(node.object.index, defs, args);
167: 
168:         return '(function () {' +
169:             '  var parent = ' + parentObject + ';' +
170:             '  ' + parentSize +
171:             '  var parentIndex = ' + parentIndex + ';' +
172:             '  var object = access(parent, parentIndex);' +
173:             '  var value = ' + value + ';' +
174:             '  ' + size +
175:             '  assign(parent, parentIndex, assign(object, ' + index + ', value));' +
176:             '  return value;' +
177:             '})()';
178:       }
179:     }
180:   }
181: 
182:   // register the compile function
183:   register(AssignmentNode.prototype.type, compileAssignmentNode);
184: 
185:   /**
186:    * Execute a callback for each of the child nodes of this node
187:    * @param {function(child: Node, path: string, parent: Node)} callback
188:    */
189:   AssignmentNode.prototype.forEach = function (callback) {
190:     callback(this.object, 'object', this);
191:     if (this.index) {
192:       callback(this.index, 'index', this);
193:     }
194:     callback(this.value, 'value', this);
195:   };
196: 
197:   /**
198:    * Create a new AssignmentNode having it's childs be the results of calling
199:    * the provided callback function for each of the childs of the original node.
200:    * @param {function(child: Node, path: string, parent: Node): Node} callback
201:    * @returns {AssignmentNode} Returns a transformed copy of the node
202:    */
203:   AssignmentNode.prototype.map = function (callback) {
204:     var object = this._ifNode(callback(this.object, 'object', this));
205:     var index = this.index
206:         ? this._ifNode(callback(this.index, 'index', this))
207:         : null;
208:     var value = this._ifNode(callback(this.value, 'value', this));
209: 
210:     return new AssignmentNode(object, index, value);
211:   };
212: 
213:   /**
214:    * Create a clone of this node, a shallow copy
215:    * @return {AssignmentNode}
216:    */
217:   AssignmentNode.prototype.clone = function() {
218:     return new AssignmentNode(this.object, this.index, this.value);
219:   };
220: 
221:   /*
222:    * Is parenthesis needed?
223:    * @param {node} node
224:    * @param {string} [parenthesis='keep']
225:    * @private
226:    */
227:   function needParenthesis(node, parenthesis) {
228:     if (!parenthesis) {
229:       parenthesis = 'keep';
230:     }
231: 
232:     var precedence = operators.getPrecedence(node, parenthesis);
233:     var exprPrecedence = operators.getPrecedence(node.value, parenthesis);
234:     return (parenthesis === 'all')
235:       || ((exprPrecedence !== null) && (exprPrecedence <= precedence));
236:   }
237: 
238:   /**
239:    * Get string representation
240:    * @param {Object} options
241:    * @return {string}
242:    */
243:   AssignmentNode.prototype._toString = function(options) {
244:     var object = this.object.toString(options);
245:     var index = this.index ? this.index.toString(options) : '';
246:     var value = this.value.toString(options);
247:     if (needParenthesis(this, options && options.parenthesis)) {
248:       value = '(' + value + ')';
249:     }
250: 
251:     return object + index + ' = ' + value;
252:   };
253: 
254:   /**
255:    * Get LaTeX representation
256:    * @param {Object} options
257:    * @return {string}
258:    */
259:   AssignmentNode.prototype._toTex = function(options) {
260:     var object = this.object.toTex(options);
261:     var index = this.index ? this.index.toTex(options) : '';
262:     var value = this.value.toTex(options);
263:     if (needParenthesis(this, options && options.parenthesis)) {
264:       value = '\\left(' + value + '\\right)';
265:     }
266: 
267:     return object + index + ':=' + value;
268:   };
269: 
270:   return AssignmentNode;
271: }
