6: /**
7:  * Test whether value is a string
8:  * @param {*} value
9:  * @return {boolean} isString
10:  */
11: exports.isString = function(value) {
12:   return typeof value === 'string';
13: };
14: 
15: /**
16:  * Check if a text ends with a certain string.
17:  * @param {string} text
18:  * @param {string} search
19:  */
20: exports.endsWith = function(text, search) {
21:   var start = text.length - search.length;
22:   var end = text.length;
23:   return (text.substring(start, end) === search);
24: };
25: 
26: /**
27:  * Format a value of any type into a string.
28:  *
29:  * Usage:
30:  *     math.format(value)
31:  *     math.format(value, precision)
32:  *
33:  * When value is a function:
34:  *
35:  * - When the function has a property `syntax`, it returns this
36:  *   syntax description.
37:  * - In other cases, a string `'function'` is returned.
38:  *
39:  * When `value` is an Object:
40:  *
41:  * - When the object contains a property `format` being a function, this
42:  *   function is invoked as `value.format(options)` and the result is returned.
43:  * - When the object has its own `toString` method, this method is invoked
44:  *   and the result is returned.
45:  * - In other cases the function will loop over all object properties and
46:  *   return JSON object notation like '{"a": 2, "b": 3}'.
47:  *
48:  * Example usage:
49:  *     math.format(2/7);                // '0.2857142857142857'
50:  *     math.format(math.pi, 3);         // '3.14'
51:  *     math.format(new Complex(2, 3));  // '2 + 3i'
52:  *     math.format('hello');            // '"hello"'
53:  *
54:  * @param {*} value             Value to be stringified
55:  * @param {Object | number | Function} [options]  Formatting options. See
56:  *                                                lib/utils/number:format for a
57:  *                                                description of the available
58:  *                                                options.
59:  * @return {string} str
60:  */
61: exports.format = function(value, options) {
62:   if (typeof value === 'number') {
63:     return formatNumber(value, options);
64:   }
65: 
66:   if (value && value.isBigNumber === true) {
67:     return formatBigNumber(value, options);
68:   }
69: 
70:   if (value && value.isFraction === true) {
71:     if (!options || options.fraction !== 'decimal') {
72:       // output as ratio, like '1/3'
73:       return (value.s * value.n) + '/' + value.d;
74:     }
75:     else {
76:       // output as decimal, like '0.(3)'
77:       return value.toString();
78:     }
79:   }
80: 
81:   if (Array.isArray(value)) {
82:     return formatArray(value, options);
83:   }
84: 
85:   if (exports.isString(value)) {
86:     return '"' + value + '"';
87:   }
88: 
89:   if (typeof value === 'function') {
90:     return value.syntax ? String(value.syntax) : 'function';
91:   }
92: 
93:   if (value && typeof value === 'object') {
94:     if (typeof value.format === 'function') {
95:       return value.format(options);
96:     }
97:     else if (value && value.toString() !== {}.toString()) {
98:       // this object has a non-native toString method, use that one
99:       return value.toString();
100:     }
101:     else {
102:       var entries = [];
103: 
104:       for (var key in value) {
105:         if (value.hasOwnProperty(key)) {
106:           entries.push('"' + key + '": ' + exports.format(value[key], options));
107:         }
108:       }
109: 
110:       return '{' + entries.join(', ') + '}';
111:     }
112:   }
113: 
114:   return String(value);
115: };
116: 
117: /**
118:  * Stringify a value into a string enclosed in double quotes.
119:  * Double quotes inside the value are escaped.
120:  * @param {*} value
121:  * @return {string}
122:  */
123: exports.stringify = function (value) {
124:   var str = String(value).replace(/([^\\]|^)"/g, function (full, before) {
125:     return before + '\\"';
126:   });
127: 
128:   return '"' + str + '"';
129: }
130: 
131: /**
132:  * Recursively format an n-dimensional matrix
133:  * Example output: "[[1, 2], [3, 4]]"
134:  * @param {Array} array
135:  * @param {Object | number | Function} [options]  Formatting options. See
136:  *                                                lib/utils/number:format for a
137:  *                                                description of the available
138:  *                                                options.
139:  * @returns {string} str
140:  */
141: function formatArray (array, options) {
142:   if (Array.isArray(array)) {
143:     var str = '[';
144:     var len = array.length;
145:     for (var i = 0; i < len; i++) {
146:       if (i != 0) {
147:         str += ', ';
148:       }
149:       str += formatArray(array[i], options);
150:     }
151:     str += ']';
152:     return str;
153:   }
154:   else {
155:     return exports.format(array, options);
156:   }
157: }

